"""Статья «Умный дом без мифов» для раздела «Справочники → Умный дом».

Исходный текст подготовлен ТЕГА ПЛЮС, здесь он проверен, исправлен и приведён к стилю сайта. Рекламный блок убран.
Что исправлено:
 - убраны цифры, которые не удалось подтвердить: объём рынка и рост (источники расходятся в разы), «~80 % домохозяйств», «10–15 % домов с комплексной системой»,
   «окупаемость хаба за 2–3 года», «15–30 % экономии» для дома целиком (оставлены только опубликованные оценки для умного термостата);
 - таблица брендов («мировой топ») и упоминания конкретных производителей убраны: проверить актуальность и наличие в Беларуси не удалось;
 - Thread не работает «без хаба»: нужен пограничный маршрутизатор (Border Router), он есть во многих хабах и колонках;
 - тарифы 0,5162 и 0,1807 BYN относятся только к случаю «электроплита, без газа»; для остальных двухзонный тариф 0,6074 и 0,2126 (постановление Совмина № 93 от 25.02.2026);
 - «облако за пределами ЕАЭС — юридический риск» заменено нейтральной ссылкой на правила трансграничной передачи персональных данных (Закон № 99-З);
 - «Zigbee и Z-Wave делят эфир 2,4 ГГц с Wi-Fi»: это верно для Zigbee и Thread, Z-Wave в Европе работает ниже 1 ГГц;
 - «умный дым вместо СМЗ/АУП» переписано: пожарная сигнализация и оповещение проектируются отдельно по нормам;
 - «ёмкость хаба 50–150 устройств», время автономности и срок батарей помечены как практика и паспорт.
Источники: Закон Республики Беларусь от 07.05.2021 № 99-З «О защите персональных данных»; постановление Совета Министров № 93 от 25.02.2026 (тарифы);
спецификации Matter (CSA); ENERGY STAR (умные термостаты); паспорта производителей.
"""
from art_heat import _sec, _ul, _tbl, _note, _box, _p, _errs, _kpis
from art_smart_figs import f_steps, f_arch


def article():
    s = ""
    s += _kpis([("100–300 мс", "отклик локальной сцены, практика; облако 0,5–2 с и зависит от сети"), ("локально", "критичная логика живёт в доме, облако только для уведомлений"),
                ("нейтраль", "в каждом подрозетнике: без неё умные выключатели не встанут"), ("ИБП", "на хаб, роутер и клапаны: час аварии не должен быть заметен")])
    s += f_steps()
    s += _box("Главный принцип",
              "Сначала сценарии и зоны, потом протокол и устройства. Фраза «хочу умный дом» без списка «что должно происходить и когда» заканчивается витриной гаджетов без пользы. "
              "Сценарии диктуют архитектуру: проводную шину закладывают в черновике, беспроводную сеть добавляют в чистовой, а гибрид закрывает и то и другое.")

    s += _sec("0", "Суть: датчик, логика, исполнитель, и три метрики",
              _p("Умный дом это не колонка и не «лампочка из приложения», а замкнутый контур: датчики (движение и присутствие, протечка, CO₂, температура, контакты окон), "
                 "логика (хаб или контроллер со сценариями) и исполнительные устройства (реле, диммеры, приводы клапанов, клавиатуры климата). Ценность дают три метрики.")
              + _ul(["<b>Отклик.</b> Локальная сцена срабатывает за доли секунды (практика 100–300 мс), через облако дольше и с зависимостью от интернета.",
                     "<b>Надёжность.</b> Работает ли дом без интернета и электричества час-два: это проверяется на приёмке, а не обещается.",
                     "<b>Энергоэффективность.</b> Климат по расписанию и присутствию, свет по присутствию, дежурные режимы. Для умных термостатов есть опубликованные оценки: ENERGY STAR называет в среднем около 8 % экономии на отоплении и охлаждении, "
                     "исследования производителей дают 10–15 %. Для дома целиком цифру задаёт ваш режим и инженерные системы: считайте по своим счетам, а не по общему проценту."])
              + _p("Практичный факт, который экономит бюджет: основную пользу дают немногие сценарии. Климат по расписанию и геозоне, свет по присутствию, защита от протечек, сцены «ушёл», «сон», «кино» "
                   "и надёжные физические кнопки. Остальное чаще всего гаджеты, которые отключают через месяц."))

    s += _sec("1", "Разновидности: проводные, беспроводные, гибридные и экосистемы",
              _tbl(["Архитектура", "Протоколы", "Плюсы", "Минусы", "Когда"], [
                  ["Проводная шинная", "KNX, DALI (свет), BACnet и Modbus (инженерные системы)", "Предсказуемая работа, срок жизни десятилетия, не зависит от эфира и облаков", "Закладывается в черновике, цена шины и пусконаладки", "Новые дома, офисы, здания"],
                  ["Беспроводная mesh", "Zigbee, Z-Wave, Thread (с Matter)", "Монтаж в чистовой, батареи месяцы и годы, сеть самовосстанавливается", "Zigbee и Thread делят 2,4 ГГц с Wi-Fi; лимит устройств на хаб по паспорту", "Квартиры, ретрофит, аренда"],
                  ["Wi-Fi и Ethernet", "Wi-Fi 2,4 и 5 ГГц, PoE-камеры", "Высокий трафик: камеры, медиа, панели", "Много устройств перегружают эфир, роуминг", "Точечно: камеры, медиа, ТВ"],
                  ["Гибрид (рабочая схема)", "Шина + mesh-надстройка + мост Matter", "Надёжность ядра и гибкость периферии", "Нужен квалифицированный интегратор", "Дом и административные здания"],
              ])
              + _p("<b>Экосистемы и мосты.</b> Потребительские платформы (Apple Home, Google Home, Amazon Alexa, Samsung SmartThings и другие) удобны, но привязывают к своему облаку. "
                   "Открытые платформы (Home Assistant, openHAB) дают локальную логику и сотни интеграций без привязки к вендору. Связующее звено это Matter, стандарт Connectivity Standards Alliance: "
                   "устройство с Matter работает сразу в нескольких экосистемах и управляется локально. Matter идёт поверх Wi-Fi, Ethernet и Thread. "
                   "Thread строит самовосстанавливающуюся mesh-сеть, но выходит в домашнюю сеть через пограничный маршрутизатор (Border Router), который есть во многих хабах и колонках.")
              + _note("Покупка устройств без Matter и открытого протокола это осознанный риск привязки к вендору: если облако закроют, устройство может перестать работать."))

    s += _sec("2", "Тенденции и что у нас",
              _ul(["<b>Matter и Thread как общий стандарт.</b> Его поддерживают крупные платформы, список сертифицированных устройств растёт. Проверяйте сертификацию конкретной модели.",
                   "<b>Local-first и приватность.</b> Сцены работают без интернета, облако остаётся для уведомлений и удалённого доступа, видео хранится дома, где это возможно.",
                   "<b>Предиктивные сценарии.</b> Расписания дополняются прогнозом погоды и учётом присутствия: дом готовит климат к приходу.",
                   "<b>Энергетическая гибкость.</b> Связка с тепловым насосом, солнечной станцией и зарядкой электромобиля, сдвиг нагрузки на дешёвые часы.",
                   "<b>Помощь пожилым.</b> Датчики присутствия и падения, сценарии «тревога»: растущая область, но медицинское оборудование и экстренная связь остаются отдельными системами."])
              + _box("А в Беларуси?",
                     "Входом в тему обычно становятся датчики протечки, климат и свет на беспроводных протоколах; комплексные объекты (коттеджи, офисы) закладывают проводную шину в черновике и поручают проект интегратору. "
                     "Для сдвига нагрузки есть двухзонные тарифы для населения (постановление Совмина № 93 от 25.02.2026): для жилья с электроплитой и без газа 0,5162 BYN днём и 0,1807 BYN ночью, "
                     "для остальных случаев 0,6074 и 0,2126 BYN за кВт·ч. Окупаемость сценариев сдвига зависит от вашей нагрузки: калькулятор «Солнечные системы» этого же раздела считает её по часам.")
              + _p("Конкретные модели и цены здесь не приводятся: наличие, сертификация и поддержка у производителей меняются, проверяйте их на момент покупки."))

    s += _sec("3", "Три типа объектов: квартира, дом, административное здание",
              f_arch()
              + _tbl(["Объект", "Рабочая конфигурация", "Ключевые сценарии и нюансы"], [
                  ["Квартира", "Беспроводной ретрофит: хаб, датчики (протечка, движение, окна), умные реле в подрозетниках, управление кондиционером", "Сцены «ушёл» и «сон», защита от протечек с клапаном, климат по геозоне, монтаж без штробления за день"],
                  ["Загородный дом", "Гибрид: шина в черновике и mesh в чистовой; интеграции котла или теплового насоса, кондиционеров и вентиляции, солнечной станции, скважины, охраны и протечек", "Климат по зонам и погоде, свет по присутствию, сценарии «гости» и «отпуск», ИБП на хаб и сеть, трассы шины закладывают до отделки"],
                  ["Административное здание", "BACnet, KNX, DALI: диспетчеризация климата и света, доступ и учёт, расписания по присутствию и CO₂", "Отчёты по энергии, зонирование по фасадам; связь с пожарной автоматикой только через нормируемые интерфейсы"],
              ])
              + _p("<b>Показатели, по которым сравнивают системы.</b> Отклик сцены (локально доли секунды, облако секунды). Ёмкость хаба: берите из паспорта, у радиохабов она ограничена десятками и сотнями устройств, у шин сотни адресов. "
                   "Автономность: ИБП держит хаб, роутер и радиоканал от десятков минут до нескольких часов в зависимости от ёмкости. Срок батарей датчиков: у Zigbee и Thread обычно месяцы и годы, у Wi-Fi-датчиков меньше. "
                   "Работа локальной логики без интернета. Стоимость владения: подписки на облако это скрытая строка бюджета."))

    s += _sec("4", "Управление: интерфейсы, автоматизации, сеть и безопасность",
              _ul(["<b>Иерархия интерфейсов.</b> Физические кнопки и сценарные клавиши первичны (гости, дети, пожилые, «нет сети»), панели и приложение вторичны, голос третий слой для занятых рук. Дом, который управляется только голосом или телефоном, не проходит приёмку.",
                   "<b>Типы автоматизаций.</b> Реактивные (датчик, действие), расписания и геозоны, предиктивные (прогноз и привычки). Правило: одна причина, одно предсказуемое действие. Каскады «если-то-если» через год никто не отладит.",
                   "<b>Локально или в облаке.</b> Вся критичная логика (климат, протечки, свет, охрана) в локальном хабе, облако для уведомлений и удалённого доступа. Тест приёмки: отключить интернет, дом не должен заметить.",
                   "<b>Сеть как инженерная система.</b> Отдельная сеть или VLAN для умных устройств, PoE для камер и точек доступа, покрытие Wi-Fi по плану, а не «роутер в коридоре». Mesh-протоколы разгружают эфир Wi-Fi.",
                   "<b>Безопасность и приватность.</b> Обновления прошивок по регламенту, уникальные пароли, смена паролей интегратора при сдаче. Видео и записи голоса о людях могут быть персональными данными: "
                   "действует Закон от 07.05.2021 № 99-З «О защите персональных данных», в нём есть правила передачи данных за границу. Для офиса и общих зон уточните требования у юриста до выбора облачной камеры."])
              + _box("Запоминалка «Три Л»", "Локально, Логично, Документировано. Локально: критичная логика живёт дома. Логично: один датчик одно действие, кнопки дублируют голос. "
                                           "Документировано: схемы, пароли и инструкции остаются владельцу, а не интегратору."))

    s += _sec("5", "Нюансы монтажа: черновик, сеть, питание, сдача",
              _ul(["<b>Черновик решает всё.</b> Шинный кабель и резервные линии закладывают до отделки. В подрозетники выключателей тянут нейтраль N: без неё умные реле и диммеры не работают. Датчики присутствия размечают на потолке с питанием или шиной, камеры идут по PoE.",
                   "<b>Питание ядра.</b> ИБП на хаб, роутер, радиоканал и клапаны протечки: час автономности превращает аварию в «не заметили». Щит умного дома отдельный, линии маркированы. Сечения и автоматы считайте в калькуляторе электрики этого раздела.",
                   "<b>Размещение датчиков.</b> Присутствие: потолок или угол с обзором зоны, а не «над диваном». Протечка: под трапом, мойкой, котлом. CO₂: в зоне дыхания спален и переговорных. Окна и двери: герконы с защитой от ложных срабатываний.",
                   "<b>Исполнительные устройства.</b> Реле и диммеры подбирают по нагрузке и типу ламп (диммируются не все LED). Клапаны протечки с возвратом и ручным дублёром. Приводы клапанов тёплых полов и радиаторов совместимы с выбранной шиной.",
                   "<b>Пусконаладка и сдача.</b> Прогон всех сцен при заказчике, тест без интернета, тест ИБП, замер отклика. В комплект сдачи входят исполнительные схемы, адреса устройств, пароли администратора, инструкция и обучение. Без этого дом после ухода интегратора превращается в чёрный ящик."])
              + _box("Чек-лист приёмки умного дома",
                     "1) Сценарии из задания работают без интернета. 2) ИБП держит ядро заявленное время. 3) Кнопки и сцены дублируют приложение и голос. 4) Все датчики в мониторинге, заряд батарей виден. "
                     "5) Пароли, схемы и адреса переданы владельцу. 6) Обновление прошивок показано. 7) Подписки и их стоимость прописаны в договоре. Эти пункты закрывают большую часть конфликтов при сдаче."))

    s += _sec("6", "Типичные ошибки: 12 способов получить дорогую игрушку",
              _errs([
                  ("Гаджеты раньше сценариев", "Коробка устройств без пользы, через месяц их отключают.", "Список «что должно происходить и когда» до сметы."),
                  ("Привязка к вендору без открытого протокола", "Экосистема закрывается, дом перестаёт работать, переезд это демонтаж.", "Устройства с Matter, Thread или открытой платформой."),
                  ("Вся логика в облаке", "Интернет пропал: свет, климат и охрана тоже.", "Локальный хаб, облако только для уведомлений и удалённого доступа."),
                  ("Нет нейтрали в подрозетниках", "Умные выключатели не ставятся без ломки готовой отделки.", "Нейтраль N в каждый подрозетник на этапе электрики."),
                  ("Wi-Fi на все устройства", "Десятки устройств перегружают эфир: отвалы и перезагрузки.", "Mesh-протоколы для датчиков, Wi-Fi только для камер и медиа."),
                  ("Нет ИБП на ядро", "Час аварии это час «глупого» дома и закрытые клапаны.", "ИБП на хаб, роутер, радио и приводы, тест при сдаче."),
                  ("Устройства в общей сети с заводскими паролями", "Камеры и доступы становятся лёгкой целью.", "Отдельная сеть, уникальные пароли, обновления по регламенту, учёт 99-З."),
                  ("Только голос и приложение", "Гости, дети и пожилые остаются без света при разряженном телефоне.", "Физические кнопки и сцены как первичный интерфейс."),
                  ("Сценарии после ремонта", "Нет шины и нейтрали: штробление готовой отделки.", "Проектировать вместе с электрикой, до отделки."),
                  ("Нет документации и паролей", "Интегратор исчез, и дом остаётся чёрным ящиком.", "Схемы, адреса, пароли и инструкция в комплекте сдачи."),
                  ("Датчики без регламента", "Севшая батарейка это тихая протечка без сигнала.", "Мониторинг батарей, проверка раз в сезон, журнал срабатываний."),
                  ("«Умный дом» вместо пожарной сигнализации", "Бытовой датчик не заменяет проектируемую пожарную сигнализацию и оповещение.", "Пожарная автоматика проектируется отдельно по нормам, умный дом лишь дублирует уведомления."),
              ]))

    s += _sec("7", "Приоритеты и чек-лист заказчика",
              _tbl(["Сегмент", "На что смотреть", "Что проверить в Беларуси"], [
                  ["Проводные шины", "KNX, DALI-2 для света, BACnet и Modbus для инженерных систем", "Наличие интегратора, проект и пусконаладка обязательны"],
                  ["Потребительские экосистемы", "Поддержка Matter, работа без облака, региональная доступность", "Доступность сервисов и поддержка в стране на момент покупки"],
                  ["Открытые платформы", "Локальная работа, число интеграций, сообщество", "Хороший выбор против привязки к вендору, нужен специалист"],
                  ["Matter и Thread", "Сертификация конкретной модели, наличие Border Router", "Поставки через розницу и маркетплейсы"],
                  ["Климат и энергия", "Шлюзы Opentherm, Modbus, BACnet к котлам, тепловым насосам, VRF и вентиляции", "Совместимость конкретных моделей по паспорту"],
              ])
              + _p("Вопросы подрядчику до договора.")
              + _ul(["Где список сценариев и зон, на который вы даёте цену, и что из него работает локально без интернета?",
                     "Какой протокол и почему: KNX, Zigbee, Thread и Matter? Что произойдёт, если облако вендора закроют?",
                     "Нейтраль и шинный кабель заложены в электрику? Кто и когда их тянет?",
                     "ИБП на ядро: что держит и сколько минут, будет ли тест при сдаче?",
                     "Что передаётся владельцу: схемы, адреса, пароли администратора, инструкции?",
                     "Подписки и облачные сервисы: стоимость в год и что перестанет работать без них?"])
              + _box("Красные флаги", "«Поставим всё на наше облако, так надёжнее»; цена без пусконаладки и обучения; умный дом вместо проекта пожарной автоматики; отказ передать пароли и схемы; "
                                      "Wi-Fi-датчики «на всё»; ни одной физической кнопки в смете. Любого пункта достаточно, чтобы не подписывать договор.")
              + _p("Пять тезисов, с которыми можно принимать решение.")
              + _ul(["Умный дом начинается со списка сценариев, а не с витрины устройств.",
                     "Локальная логика и открытые протоколы (Matter, Thread, KNX) защищают от закрытия облаков и вендоров; облако оставляют уведомлениям, а не выключателям.",
                     "Экономия измеряется энергией: считайте по своим счетам и тарифу, а не по общим процентам.",
                     "Надёжность живёт в черновике: нейтраль в подрозетниках, шинный кабель до отделки, ИБП на ядро, отдельная сеть для умных устройств.",
                     "Приёмка это документы и тесты: сцены без интернета, ИБП под нагрузкой, пароли и схемы владельцу."])
              + _note("Источники: Закон Республики Беларусь от 07.05.2021 № 99-З «О защите персональных данных»; постановление Совета Министров № 93 от 25.02.2026 (тарифы); "
                      "ENERGY STAR (умные термостаты); спецификации Matter (CSA); паспорта производителей. Пожарная автоматика проектируется по действующим нормам отдельно от умного дома. Оценки не оферта."))
    return s
